// Each occupied slot keeps its submitted path on the table, including sketches and
// portraits generated by a phone. Write the unused bank first; changing the RAM
// references publishes all three paths together. A reset invalidates the sand map.
struct GuestSlotFile {
  uint16_t count;
  uint8_t bank;
};
GuestSlotFile guestFiles[3]={};

File openGuestSlot(int slot, uint8_t bank, const char* mode) {
  char path[20];
  snprintf(path,sizeof path,"/scene%d-%d.bin",slot,(int)bank);
  return LittleFS.open(path,mode);
}
bool validGuestPath(File& file, uint32_t offset, long count, int slot, bool photo) {
  if (count<2 || count>MAXPTS || !file.seek(offset)) return false;
  float angle=(-150+120*slot)*(float)M_PI/180;
  float cx=.555f*cosf(angle), cy=.555f*sinf(angle);
  Pt points[64], previous={};
  for (long pos=0;pos<count;) {
    long n=min(64L,count-pos);
    if (file.read((uint8_t*)points,n*sizeof(Pt))!=n*sizeof(Pt)) return false;
    for (long i=0;i<n;i++,pos++) {
      Pt p=points[i];
      if (!isfinite(p.theta) || fabsf(p.theta)>10000 || !isfinite(p.rho) || p.rho<0 || p.rho>1 ||
          (pos && fabsf(p.theta-previous.theta)>3.15f)) return false;
      if ((!pos || (!photo && pos==count-1)) && p.rho<.997f) return false;
      if (slot>=0 && p.rho<.997f) {
        float dx=p.rho*cosf(p.theta)-cx,dy=p.rho*sinf(p.theta)-cy;
        if (dx*dx+dy*dy>.455f*.455f) return false;
      }
      if (slot>=0 && pos && (p.rho<.997f || previous.rho<.997f) &&
          (fabsf(p.theta-previous.theta)>.5f || fabsf(p.rho-previous.rho)>.055f)) return false;
      previous=p;
    }
  }
  return true;
}
// Call while webFlash holds motion off. A failed stage leaves the live bank alone.
bool stageGuestSlot(File& source, uint32_t offset, int slot, uint16_t count, GuestSlotFile& dest) {
  if (!source.seek(offset)) return false;
  uint8_t bank=1-guestFiles[slot].bank;
  File out=openGuestSlot(slot,bank,"w");
  if (!out) return false;
  uint8_t buf[512]; uint32_t left=count*sizeof(Pt);
  while (left) {
    size_t n=left>sizeof buf ? sizeof buf : left;
    if (source.read(buf,n)!=n || out.write(buf,n)!=n) return false;
    left-=n;
  }
  out.close();
  File check=openGuestSlot(slot,bank,"r");
  if (!check || check.size()!=count*sizeof(Pt) || !validGuestPath(check,0,count,slot,false)) return false;
  dest.count=count; dest.bank=bank;
  return true;
}
bool guestFilesReady(const GuestSlotFile files[], const char slots[][41]) {
  for (int i=0;i<3;i++) {
    if (!slots[i][0]) continue;
    File f=openGuestSlot(i,files[i].bank,"r");
    if (!f || f.size()!=files[i].count*sizeof(Pt) || !validGuestPath(f,0,files[i].count,i,false)) return false;
  }
  return true;
}
bool loadGuestSlot(int slot) {
  GuestSlotFile src=guestFiles[slot];
  File f=openGuestSlot(slot,src.bank,"r");
  size_t bytes=src.count*sizeof(Pt);
  patN=0;
  if (!f || src.count<2 || src.count>MAXPTS || f.size()!=bytes || f.read((uint8_t*)pat,bytes)!=bytes) return false;
  patN=src.count;
  return true;
}
